+func chickMissingFlags(children []*Branch, flags []*Flag) error {
+	// Only check required missing fields at the last child.
+	if len(children) > 0 {
+		return nil
+	}
+	missing := []string{}
+	for _, flag := range flags {
+		if !flag.Required || flag.Set {
